  		clsCommonWeb.ClickButton(objDictionary, driver, "Parking Session", "Approve/Reject Violation", 1,"Local");
  		try {Thread.sleep(1000);}catch (Exception e) {}
  		clsCommonWeb.PopulateAction(objDictionary, driver, "Parking Session", "Populate Reject Violation", "{RB} Violation Type|{L} Violation reject reason", "Reject Violation|Coin Errors");
  		clsCommonWeb.ClickButton(objDictionary, driver, "Parking Session", "Approve/Reject Violation-Dialog", 1,"Local");
  		driver.quit();
  		//VMVE: Validate Meter Violation Exists
  		clsMeter.METER_ValidateMeterViolated(objDictionary, null,"1","Local");
  		//ShortSessionWaitExitSpot
  		clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary, null, "1","Local");
